function useCatalogProducts(type:'resource'|'server'){const [items,setItems]=useState<CatalogProduct[]>([]);useEffect(()=>{if(!getApiBase())return;let active=true;apiFetch('/api/catalog').then(apiJson).then(data=>{if(active&&Array.isArray(data.products))setItems(data.products.filter((x:CatalogProduct)=>x.type===type))}).catch(()=>{});return()=>{active=false}},[type]);return items}

